-- Source: database/functions/organization_verification/notifications.sql
-- Internal producer shared by submission and an explicitly scoped repair.
CREATE OR REPLACE FUNCTION public.enqueue_unit_verification_request(p_unit bigint)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; u public.units; o public.organizations; a record; msg jsonb; n integer:=0; origin text;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 SELECT * INTO u FROM public.units WHERE id=p_unit FOR UPDATE;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p.status IS DISTINCT FROM 'pending' OR public.is_demo_unit(p_unit) THEN RETURN 0; END IF;
 SELECT * INTO o FROM public.organizations WHERE id=u.organization;
 origin:=rtrim(o.data->>'DEFAULT_URL','/');
 IF origin IS NULL OR origin !~ '^https://[^/?#[:space:]]+$' THEN RAISE EXCEPTION 'verification_notification_origin_missing'; END IF;
 FOR a IN SELECT ou."user" id,public.get_user_delivery_email(ou."user") email
  FROM public.organization_users ou WHERE ou.organization=u.organization AND ou.is_admin ORDER BY ou."user"
 LOOP
  IF a.email IS NULL THEN CONTINUE; END IF;
  msg:=public.enqueue_email('custom',jsonb_build_object('organization',u.organization,'unit',p_unit,'recipient_user',a.id),a.email,
   jsonb_build_object('unit_id',p_unit,'revision',p.revision,'legal_name',p.legal_name,'registration_number',p.registration_number,
    'review_url',origin||'/organizationEdit/'||u.organization,'app_name',o.title),
   'unit-verification:'||p_unit||':'||p.revision||':'||a.id,'UNIT_VERIFICATION_REQUEST',now(),now()+interval '30 days',NULL,p.revision);
  UPDATE public.email_messages SET tracking_policy='disabled' WHERE message_id=(msg->>'message_id')::uuid;
  n:=n+1;
 END LOOP;
 RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.enqueue_unit_verification_request(bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.enqueue_unit_verification_request(bigint) TO service_role;

-- Source: database/functions/organization_verification/profile_commands.sql
CREATE OR REPLACE FUNCTION public.get_unit_legal_profile(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; org bigint; admin boolean; result jsonb;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit;
 admin:=coalesce(public.check_is_admin_of_organization(org),false);
 IF auth.uid() IS NULL OR org IS NULL OR NOT (public.get_is_manager_on_unit(p_unit) OR admin) THEN
  RAISE EXCEPTION 'Legal profile access denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit;
 result:=jsonb_build_object('unitId',p_unit,'revision',coalesce(p.revision,0),'status',coalesce(p.status,'unverified'),
 'legalName',coalesce(p.legal_name,''),'countryCode',coalesce(p.country_code,''),
 'registrationNumber',coalesce(p.registration_number,''),'vatId',coalesce(p.vat_id,''),
 'address',jsonb_build_object('street',coalesce(p.street,''),'city',coalesce(p.city,''),'postalCode',coalesce(p.postal_code,'')),
 'contactEmail',coalesce(p.contact_email,''),'phone',coalesce(p.phone,''),'website',coalesce(p.website,''),
 'submittedAt',p.submitted_at,'verifiedAt',CASE WHEN p.status='verified' AND p.reviewed_organization_id=org THEN p.reviewed_at END,
 'feedbackToApplicant',CASE WHEN p.reviewed_organization_id=org THEN p.feedback_to_applicant END);
 IF admin AND p.reviewed_organization_id=org THEN
  result:=result||jsonb_build_object('reviewNote',p.review_note,'reviewSource',p.review_source);
 END IF;
 RETURN jsonb_build_object('code',200,'profile',result);
END $$;

CREATE OR REPLACE FUNCTION public.save_unit_legal_profile(p_unit bigint,p_expected_revision bigint,p_profile jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; n public.unit_legal_profiles; org bigint; k text; v text;
 errors jsonb:='{}'; normalized jsonb; old_values jsonb; checksum integer:=0; i integer;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.get_is_manager_on_unit(p_unit) OR public.is_demo_unit(p_unit) THEN
  RAISE EXCEPTION 'Legal profile write denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN
  RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile');
 END IF;
 IF jsonb_typeof(p_profile) IS DISTINCT FROM 'object' THEN
  RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',jsonb_build_object('profile','OBJECT_REQUIRED'));
 END IF;
 FOR k IN SELECT jsonb_object_keys(p_profile) LOOP
  IF k<>ALL(ARRAY['legalName','countryCode','registrationNumber','vatId','address','contactEmail','phone','website']) THEN errors:=errors||jsonb_build_object(k,'UNKNOWN_FIELD'); END IF;
  IF k<>'address' AND jsonb_typeof(p_profile->k) NOT IN ('string','null') THEN errors:=errors||jsonb_build_object(k,'TEXT_REQUIRED'); END IF;
 END LOOP;
 IF p_profile ? 'address' AND jsonb_typeof(p_profile->'address') IS DISTINCT FROM 'object' THEN
  errors:=errors||jsonb_build_object('address','OBJECT_REQUIRED');
 ELSE
  FOR k IN SELECT jsonb_object_keys(coalesce(p_profile->'address','{}')) LOOP
   IF k<>ALL(ARRAY['street','city','postalCode']) THEN errors:=errors||jsonb_build_object('address.'||k,'UNKNOWN_FIELD'); END IF;
   IF jsonb_typeof(p_profile->'address'->k) NOT IN ('string','null') THEN errors:=errors||jsonb_build_object('address.'||k,'TEXT_REQUIRED'); END IF;
  END LOOP;
 END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',errors); END IF;
 n.legal_name:=btrim(coalesce(p_profile->>'legalName',''));
 n.country_code:=upper(btrim(coalesce(p_profile->>'countryCode','')));
 n.registration_number:=btrim(coalesce(p_profile->>'registrationNumber',''));
 n.vat_id:=btrim(coalesce(p_profile->>'vatId',''));
 n.street:=btrim(coalesce(p_profile#>>'{address,street}',''));
 n.city:=btrim(coalesce(p_profile#>>'{address,city}',''));
 n.postal_code:=btrim(coalesce(p_profile#>>'{address,postalCode}',''));
 n.contact_email:=lower(btrim(coalesce(p_profile->>'contactEmail','')));
 n.phone:=btrim(coalesce(p_profile->>'phone',''));
 n.website:=btrim(coalesce(p_profile->>'website',''));
 normalized:=jsonb_build_object('legalName',n.legal_name,'countryCode',n.country_code,'registrationNumber',n.registration_number,
 'vatId',n.vat_id,'address',jsonb_build_object('street',n.street,'city',n.city,'postalCode',n.postal_code),
 'contactEmail',n.contact_email,'phone',n.phone,'website',n.website);
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(normalized-'address') LOOP
  IF length(v)>(CASE k WHEN 'legalName' THEN 200 WHEN 'contactEmail' THEN 254 WHEN 'website' THEN 500 WHEN 'phone' THEN 40 WHEN 'countryCode' THEN 2 ELSE 50 END)
   OR v ~ '[[:cntrl:]]' THEN errors:=errors||jsonb_build_object(k,'INVALID_LENGTH_OR_CHARACTERS'); END IF;
 END LOOP;
 IF length(n.street)>200 OR length(n.city)>100 OR length(n.postal_code)>20 OR (n.street||n.city||n.postal_code) ~ '[[:cntrl:]]' THEN errors:=errors||jsonb_build_object('address','INVALID_ADDRESS'); END IF;
 IF n.country_code<>'' AND n.country_code !~ '^[A-Z]{2}$' THEN errors:=errors||jsonb_build_object('countryCode','INVALID_COUNTRY'); END IF;
 IF n.registration_number<>'' AND n.country_code='CZ' THEN
  IF n.registration_number !~ '^[0-9]{8}$' THEN errors:=errors||jsonb_build_object('registrationNumber','INVALID_CZ_ICO');
  ELSE
   FOR i IN 1..7 LOOP checksum:=checksum+substring(n.registration_number,i,1)::integer*(9-i); END LOOP;
   IF ((11-checksum%11)%10)<>substring(n.registration_number,8,1)::integer THEN errors:=errors||jsonb_build_object('registrationNumber','INVALID_CZ_ICO'); END IF;
  END IF;
 END IF;
 IF n.contact_email<>'' AND n.contact_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN errors:=errors||jsonb_build_object('contactEmail','INVALID_EMAIL'); END IF;
 IF n.phone<>'' AND n.phone !~ '^[+0-9][0-9 ()-]{2,39}$' THEN errors:=errors||jsonb_build_object('phone','INVALID_PHONE'); END IF;
 IF n.website<>'' AND n.website !~ '^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]{1,5})?([/?#][^[:space:]<>]*)?$' THEN errors:=errors||jsonb_build_object('website','HTTPS_REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',errors); END IF;
 old_values:=(public.get_unit_legal_profile(p_unit)->'profile')-ARRAY['unitId','revision','status','submittedAt','verifiedAt','feedbackToApplicant','reviewNote','reviewSource'];
 IF normalized=old_values AND (p.reviewed_organization_id IS NULL OR p.reviewed_organization_id=org) THEN
  RETURN jsonb_build_object('code',200,'outcome','unchanged','profile',public.get_unit_legal_profile(p_unit)->'profile');
 END IF;
 INSERT INTO public.unit_legal_profiles(unit_id,revision,legal_name,country_code,registration_number,vat_id,street,city,postal_code,contact_email,phone,website)
 VALUES(p_unit,coalesce(p.revision,0)+1,n.legal_name,n.country_code,n.registration_number,n.vat_id,n.street,n.city,n.postal_code,n.contact_email,n.phone,n.website)
 ON CONFLICT(unit_id) DO UPDATE SET revision=excluded.revision,status='unverified',legal_name=excluded.legal_name,
 country_code=excluded.country_code,registration_number=excluded.registration_number,vat_id=excluded.vat_id,
 street=excluded.street,city=excluded.city,postal_code=excluded.postal_code,contact_email=excluded.contact_email,
 phone=excluded.phone,website=excluded.website,submitted_at=NULL,submitted_by=NULL,reviewed_at=NULL,reviewed_by=NULL,
 reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'save',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $$;

CREATE OR REPLACE FUNCTION public.submit_unit_verification(p_unit bigint,p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; org bigint; errors jsonb:='{}'; k text; v text;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.get_is_manager_on_unit(p_unit) OR public.is_demo_unit(p_unit) THEN
  RAISE EXCEPTION 'Legal profile submission denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile'); END IF;
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(public.get_unit_legal_profile(p_unit)->'profile') WHERE key=ANY(ARRAY['legalName','countryCode','registrationNumber','contactEmail']) LOOP
  IF coalesce(v,'')='' THEN errors:=errors||jsonb_build_object(k,'REQUIRED'); END IF;
 END LOOP;
 IF coalesce(p.street,'')='' OR coalesce(p.city,'')='' OR coalesce(p.postal_code,'')='' THEN errors:=errors||jsonb_build_object('address','REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INCOMPLETE_PROFILE','fieldErrors',errors); END IF;
 IF p.status NOT IN ('unverified','rejected','revoked') THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_TRANSITION','fieldErrors','{}'::jsonb); END IF;
 UPDATE public.unit_legal_profiles SET revision=revision+1,status='pending',submitted_at=statement_timestamp(),submitted_by=auth.uid(),
 reviewed_at=NULL,reviewed_by=NULL,reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL WHERE unit_id=p_unit;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'submit',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 PERFORM public.enqueue_unit_verification_request(p_unit);
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $$;
REVOKE ALL ON FUNCTION public.get_unit_legal_profile(bigint),public.save_unit_legal_profile(bigint,bigint,jsonb),public.submit_unit_verification(bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_unit_legal_profile(bigint),public.save_unit_legal_profile(bigint,bigint,jsonb),public.submit_unit_verification(bigint,bigint) TO authenticated;

-- Source: database/functions/units/delete_unit.sql
CREATE OR REPLACE FUNCTION public.delete_unit(p_unit_id bigint)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_manager_count integer;
BEGIN
    PERFORM public.check_is_manager_on_unit(p_unit_id);

    IF EXISTS (SELECT 1 FROM public.occasions WHERE unit = p_unit_id) THEN
        RAISE EXCEPTION 'UNIT_HAS_OCCASIONS';
    END IF;

    SELECT count(*)
      INTO v_manager_count
      FROM public.unit_users
     WHERE "user" = auth.uid()
       AND is_manager = true;

    IF v_manager_count <= 1 THEN
        RAISE EXCEPTION 'CANNOT_DELETE_LAST_UNIT';
    END IF;

    -- Preserve notification history without retaining a deleted unit or live intent.
    UPDATE public.email_messages
       SET unit = NULL,
           workflow_state = CASE WHEN workflow_state IN ('pending','retry_wait','blocked','preparing')
                                 THEN 'cancelled' ELSE workflow_state END
     WHERE unit = p_unit_id AND message_kind = 'custom' AND code = 'UNIT_VERIFICATION_REQUEST';

    DELETE FROM public.unit_users WHERE unit = p_unit_id;
    DELETE FROM public.units WHERE id = p_unit_id;
END;
$$;

REVOKE ALL ON FUNCTION public.delete_unit(bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.delete_unit(bigint) TO authenticated;

-- Source: database/functions/emails/email_queue.sql (email_intent_valid only)
CREATE OR REPLACE FUNCTION public.email_intent_valid(p_message public.email_messages) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_pi eshop.payment_info; v_occ public.occasions; v_form public.forms; v_feature jsonb; v_deposit jsonb;
BEGIN
 PERFORM public.require_service_role();
 IF public.is_demo_occasion(p_message.occasion) THEN RETURN false; END IF;
 IF p_message.expires_at<=now() THEN RETURN false; END IF;
 IF p_message.message_kind='custom' AND p_message.code='UNIT_VERIFICATION_REQUEST' THEN
  RETURN EXISTS(SELECT 1 FROM public.unit_legal_profiles p JOIN public.units u ON u.id=p.unit_id
   JOIN public.organization_users ou ON ou.organization=u.organization AND ou."user"=p_message.recipient_user AND ou.is_admin
   WHERE p.unit_id=p_message.unit AND u.organization=p_message.organization AND p.status='pending'
    AND p.revision=p_message.source_version
    AND public.get_user_delivery_email(ou."user")=p_message.recipient);
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='BANK_SYNC_WARNING' THEN
  IF NOT EXISTS (SELECT 1 FROM eshop.bank_sync_health h JOIN eshop.bank_sync_connections c ON c.id=h.connection_id
    WHERE h.connection_id=(p_message.data->>'connection_id')::bigint
      AND h.incident_id::text=p_message.data->>'incident_id' AND h.warning_code IS NOT NULL
      AND c.state IN ('connected','degraded') AND public.bank_sync_problem(c.id) IS NOT NULL
      AND EXISTS(SELECT 1 FROM eshop.bank_account_users bau WHERE bau."user"=p_message.recipient_user AND bau.is_admin
        AND (bau.bank_account=c.bank_account_id OR bau.bank_account IN
          (SELECT x.bank_account_id FROM eshop.bank_sync_account_aliases x WHERE x.connection_id=c.id)))) THEN RETURN false; END IF;
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='ORDER_OVERVIEW' THEN RETURN false; END IF;
 IF p_message.order_id IS NULL THEN
  IF p_message.recipient_user IS NOT NULL AND p_message.message_kind<>'deletion_complete' THEN
   IF p_message.message_kind<>'gotrue' AND public.get_user_delivery_email(p_message.recipient_user) IS DISTINCT FROM p_message.recipient THEN RETURN false; END IF;
   IF p_message.data ? 'sign_in_code_version' AND NOT EXISTS(SELECT 1 FROM public.sign_in_codes WHERE user_id=p_message.recipient_user AND version::text=p_message.data->>'sign_in_code_version' AND expires_at>now() AND consumed_at IS NULL AND attempts<5) THEN RETURN false; END IF;
   IF p_message.data ? 'password_version' AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_message.recipient_user AND encode(extensions.digest(encrypted_password,'sha256'),'hex')=p_message.data->>'password_version') THEN RETURN false; END IF;
   IF p_message.data ? 'reset_hash' AND NOT EXISTS(SELECT 1 FROM public.user_reset_token WHERE "user"=p_message.recipient_user AND encode(extensions.digest(token::text,'sha256'),'hex')=p_message.data->>'reset_hash') THEN RETURN false; END IF;
  END IF;
  IF p_message.data ? 'deletion_request' AND NOT EXISTS(SELECT 1 FROM public.account_deletion_requests WHERE id=(p_message.data->>'deletion_request')::uuid AND status IN ('email_pending','email_sent') AND expires_at>now()) THEN RETURN false; END IF;
  IF p_message.data ? 'google_attempt' AND NOT EXISTS(SELECT 1 FROM public.external_login_attempts WHERE id=(p_message.data->>'google_attempt')::uuid AND mailbox_hash=p_message.data->>'mailbox_hash' AND expires_at>now() AND NOT mailbox_verified) THEN RETURN false; END IF;
  RETURN true;
 END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=p_message.order_id;
 IF v_order.id IS NULL OR v_order.occasion<>p_message.occasion THEN RETURN false; END IF;
 IF p_message.message_kind='custom' AND p_message.code='ORDER_OVERVIEW' THEN
  RETURN v_order.data->>'email'=p_message.recipient AND EXISTS(
   SELECT 1 FROM eshop.order_overview_sources s JOIN eshop.waitlist_capabilities c USING(token_hash)
   WHERE s.command_id=(p_message.data->>'order_overview_command')::uuid AND c.kind='order_view'
   AND c.order_id=v_order.id AND c.form_id=v_order.form AND c.organization_id=p_message.organization
   AND c.revoked_at IS NULL AND c.expires_at>now() AND s.expires_at=c.expires_at);
 END IF;
 IF p_message.message_kind='waitlist_confirmation' THEN
  RETURN v_order.state='waitlisted' AND v_order.data->>'email'=p_message.recipient;
 END IF;
 IF p_message.message_kind='waitlist_offer' THEN
  RETURN v_order.state='waitlisted' AND v_order.data->>'email'=p_message.recipient AND EXISTS(
   SELECT 1 FROM eshop.waitlist_offers w JOIN eshop.waitlist_offer_slots s ON s.offer_id=w.id
   WHERE w.id=(p_message.data->>'offer_id')::uuid AND w.order_id=v_order.id AND w.expires_at>clock_timestamp() AND s.outcome='pending');
 END IF;
 IF p_message.message_kind='order_storno' THEN RETURN true; END IF;
 IF v_order.state IN ('storno','expired','preparing_payment') THEN RETURN false; END IF;
 IF p_message.message_kind IN ('order_payment_notice','order_tickets') THEN
  RETURN v_order.state IN ('paid','sent') AND v_order.email_payment_version=p_message.source_version
   AND (p_message.data->>'manual'='true' OR v_order.data->>'email'=p_message.recipient);
 END IF;
 IF p_message.message_kind='order_reminder' THEN
  SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
  SELECT * INTO v_occ FROM public.occasions WHERE id=v_order.occasion;
  SELECT * INTO v_form FROM public.forms WHERE id=v_order.form;
  SELECT x INTO v_feature FROM jsonb_array_elements(v_occ.features) x WHERE x->>'code'='form';
  SELECT x INTO v_deposit FROM jsonb_array_elements(v_occ.features) x WHERE x->>'code'='deposit';
  IF p_message.target_time<now()-interval '7 days' OR p_message.source_version IS DISTINCT FROM v_pi.email_reminder_version
   OR coalesce((v_feature->>'is_enabled')::boolean,false)=false
   OR coalesce((v_form.data->>'is_reminder_enabled')::boolean,(v_feature->>'reminder_is_enabled')::boolean,true)=false THEN RETURN false; END IF;
  IF (p_message.data->>'is_deposit_reminder')::boolean IS TRUE THEN
   RETURN v_order.state IN ('paid','sent') AND v_pi.deposit_amount IS NOT NULL AND v_pi.paid<v_pi.amount
    AND (v_deposit->>'is_enabled')::boolean IS TRUE AND v_deposit->>'deposit_deadline' IS DISTINCT FROM 'on_site';
  END IF;
  RETURN v_order.state='ordered' AND v_pi.deadline IS NOT NULL AND coalesce((v_pi.data->>'current_version_reminded')::boolean,false)=false;
 END IF;
 RETURN true;
END $$;
COMMIT;
